var map=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().First(g=>g.name.StartsWith("Blackpine"));
return new {geometry=map.GetComponentsInChildren<Renderer>().Where(r=>r.name=="Road"||r.name=="Bridge").Select(r=>new{name=r.name,bounds=r.bounds.ToString(),rotation=r.transform.eulerAngles.ToString(),surface=UnityEditor.EditorJsonUtility.ToJson(r.GetComponent<Unity.AI.Navigation.NavMeshSurface>())}).ToArray(),prefabs=new[]{"Assets/Prefabs/ArcherTower1.prefab","Assets/Prefabs/MegicTower1.prefab","Assets/Prefabs/UnitTower1.prefab"}.Select(p=>new{path=p,tree=UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(p).GetComponentsInChildren<Transform>(true).Select(t=>new{name=t.name,scale=t.localScale.ToString(),pos=t.localPosition.ToString(),components=t.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray()}).ToArray()}).ToArray(),nav=UnityEngine.AI.NavMesh.CalculateTriangulation().vertices.Length};
